nextflow_process {

    name "Test Process BWA_ALN"
    tag "modules_nfcore"
    tag "modules"
    tag "bwa"
    tag "bwa/aln"
    tag "bwa/index"
    script "../main.nf"
    process "BWA_ALN"

    test("Single-End") {

        setup {
            run("BWA_INDEX") {
                script "../../index/main.nf"
                process {
                    """
                    input[0] = [
                        [id: 'test'],
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                    ]
                    input[1] = []
                    """
                }
            }
        }

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:true ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                    ]
                ]
                input[1] = BWA_INDEX.out.index
                """
            }
        }

        then {
            process.success
            assertAll(
                { assert snapshot(
                    file(process.out.sai[0][1]).name,
                    process.out.findAll { key, val -> key.startsWith("versions") }
                    ).match() }
            )
        }

    }

    test("Paired-End") {

        setup {
            run("BWA_INDEX") {
                script "../../index/main.nf"
                process {
                    """
                    input[0] = [
                        [id: 'test'],
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                    ]
                    input[1] = []
                    """
                }
            }
        }

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
                ]
                input[1] = BWA_INDEX.out.index
                """
            }
        }

        then {
            process.success
            assertAll(
                { assert snapshot(
                    file(process.out.sai[0][1][0]).name,
                    file(process.out.sai[0][1][1]).name,
                    process.out.findAll { key, val -> key.startsWith("versions") }
                    ).match() }
            )
        }
    }

    test("Paired-End -- stub") {
        options "-stub"
        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
                ]
                input[1] = [[], []]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out
                ).match() }
            )
        }
    }

    test("Single-End -- stub") {
        options "-stub"
        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:true ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                    ]
                ]
                input[1] = [[], []]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out
                ).match() }
            )
        }
    }

}

